using MediatR; using PartyNL.Application.Abstractions.Repositories; using PartyNL.Domain.Enums;
namespace PartyNL.Application.Features.Events.Commands.UpdateEvent;
public sealed record UpdateEventCommand(Guid Id,Guid OrganizerId,Guid LocationId,string Title,string? Description,DateTime StartDate,DateTime EndDate,decimal Price,int Capacity,int MinimumAge,EventVisibility Visibility,EventStatus Status,string? CoverImageUrl):IRequest<UpdateEventResponse>;public sealed record UpdateEventResponse(Guid Id,Guid OrganizerId,Guid LocationId,string Title,string? Description,DateTime StartDate,DateTime EndDate,decimal Price,int Capacity,int MinimumAge,EventVisibility Visibility,EventStatus Status,string? CoverImageUrl);
public sealed class UpdateEventHandler(IEventRepository repository):IRequestHandler<UpdateEventCommand,UpdateEventResponse>{public async Task<UpdateEventResponse> Handle(UpdateEventCommand request,CancellationToken cancellationToken){var e=await repository.GetByIdAsync(request.Id)??throw new KeyNotFoundException($"Event with ID '{request.Id}' was not found.");e.OrganizerId=request.OrganizerId;e.LocationId=request.LocationId;e.Title=request.Title;e.Description=request.Description;e.StartDate=request.StartDate;e.EndDate=request.EndDate;e.Price=request.Price;e.Capacity=request.Capacity;e.MinimumAge=request.MinimumAge;e.Visibility=request.Visibility;e.Status=request.Status;e.CoverImageUrl=request.CoverImageUrl;await repository.UpdateAsync(e);return new(e.Id,e.OrganizerId,e.LocationId,e.Title,e.Description,e.StartDate,e.EndDate,e.Price,e.Capacity,e.MinimumAge,e.Visibility,e.Status,e.CoverImageUrl);}}